/* Target effective UID for privilege change */
uid_t target_euid = getuid(); /* Safe, dropping to real UID */
// uid_t target_euid = 0;     /* Requires privilege (root) */

/* Set the effective user ID */
int status = seteuid(target_euid);

if (status == -1) {
    /* Errors: EPERM (Not privileged/Invalid ID), EINVAL */
    perror("seteuid failed");
    return;
}

/* Verify change using geteuid() */
if (geteuid() != target_euid) {
    // Error condition reached, though seteuid returned 0
}
